        let most_valuable_part = find_most_valuable_part(parts)
        print_str(warehouse)
        print(total_value)
        print(low_stock_count)
        print_str(most_valuable_part)
    }
    let north_total = sum(map(north_parts, calculate_value))
    let south_total = sum(map(south_parts, calculate_value))
    if north_total > south_total {
        print_str("North")
    } else {
        print_str("South")
    }
}

