    let mut inc = 0
    let mut dec = 0
    for i in range(1, len(v)) {
        if v[i] > v[i - 1] {
            inc += 1
        } else if v[i] < v[i - 1] {
            dec += 1
        }
    }
    (inc, dec)
}
fn largest_increase(v: Vec<Int>) -> Int {
    let mut max_inc = 0
    for i in range(1, len(v)) {
        let inc = v[i] - v[i - 1]
        if inc > max_inc {
            max_inc = inc
        }
    }
    max_inc
}
fn longest_stretch(v: Vec<Int>) -> Int {
    let mut max_stretch = 0
    let mut current_stretch = 0
    for i in range(1, len(v)) {
        if v[i] > v[i - 1] {
            current_stretch += 1
        } else {
            if current_stretch > max_stretch {
                max_stretch = current_stretch
            }
            current_stretch = 0
        }
    }
    if current_stretch > max_stretch {
        max_stretch = current_stretch
    }
    max_stretch
}
